pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Provide the test contract with enough ether to forward
        vm.deal(address(this), 10 ether);
        // Put 2 ether with unlockTime = block.timestamp (immediate unlock)
        c.Put{value: 2 ether}(block.timestamp);
        // Warp past the unlock time
        vm.warp(block.timestamp + 1);
        // Collect 1 ether
        c.Collect(1 ether);
        // In the reference, LogFile.History.length becomes 2 (Put + Collect)
        // In the buggy version, Collect lacks LogFile.AddMessage, so length is 1
        uint256 len = c.LogFile().History.length();
        assertEq(len, 2);
    }
}

