pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        vm.deal(address(this), 10 ether);
        c.Put{value: 2 ether}(block.timestamp + 100);
        vm.warp(block.timestamp + 200);
        c.Collect(1 ether);
        (address sender,,,,) = c.History(0);
        assertTrue(sender != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Alisa puts 1 ether, then immediately tries to collect
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(0);

        // Now alice tries to collect 1 ether right away (unlockTime is current block.timestamp, so block.timestamp > unlockTime is false)
        vm.prank(alice);
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }
        // Reference: Collect reverts because block.timestamp <= unlockTime, so balance remains 1 ether
        // Modified: Collect also reverts, but the difference is the missing LogFile.AddMessage in Put
        // So we check that the balance is still 1 ether (i.e., Collect didn't succeed)
        assertEq(c.Acc(alice).balance, 1 ether);
    }
}

