        // Setup: fund the contract and set unlock time in the past
        vm.deal(address(c), 2 ether);
        // First, a user must Put to have a balance
        address user = address(0x1234);
        vm.deal(user, 5 ether);
        vm.prank(user);
        c.Put{value: 2 ether}(0); // unlockTime = block.timestamp (now)
        // Warp to after unlockTime
        vm.warp(block.timestamp + 1 days);
        // Now user tries to Collect 1 ether, but the call will fail because target (Log contract) has no receive
        // However, the Collect will call msg.sender.call which fails because user is a plain address
        // Reference: does NOT subtract balance on failed call
        // Buggy: subtracts balance even on failed call (if (!_s) instead of if (_s))
        vm.prank(user);
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // The call itself does not revert; it just executes the conditional
        // Check balance after the call: reference leaves balance unchanged (2 ether), buggy sets it to 1 ether
        // Public getter Acc returns (unlockTime, balance)
        (uint256 unlockTime, uint256 balance) = c.Acc(user);
        // Reference: balance == 2 ether; Buggy: balance == 1 ether
        assertEq(balance, 2 ether);
    }
}

